### 8. Service 层
```java
// [K] Service 业务层
package com.example.demo.service;

import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;
import com.example.demo.entity.User;
import com.example.demo.mapper.UserMapper;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.List;

@Service // [K] 标记为 Service
public class UserService {

    @Autowired // [K] 自动注入
    private UserMapper userMapper;

    // 注册
    public String register(User user) {
        // [K] QueryWrapper 条件构造器
        QueryWrapper<User> qw = new QueryWrapper<>();
        qw.eq("username", user.getUsername());
        if (userMapper.selectCount(qw) > 0) {
            return "用户名已存在";
        }
        userMapper.insert(user); // [K] 插入
        return "注册成功";
    }

    // 登录
    public User login(String username, String password) {
        QueryWrapper<User> qw = new QueryWrapper<>();
        qw.eq("username", username).eq("password", password);
        return userMapper.selectOne(qw); // [K] 查询单条
    }

    // 查询全部
    public List<User> list() {
        return userMapper.selectList(null); // [K] 查询列表
    }

    // 新增
    public void add(User user) {
        userMapper.insert(user);
    }

    // 修改
    public void update(User user) {
        userMapper.updateById(user); // [K] 按 id 更新
    }

    // 删除
    public void delete(Integer id) {
        userMapper.deleteById(id); // [K] 按 id 删除
    }
}
```

### 9. Controller 层
```java
// [K] Controller 控制层
package com.example.demo.controller;

import com.example.demo.common.Result;
import com.example.demo.entity.User;
import com.example.demo.service.UserService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController // [K] REST 控制器
@RequestMapping("/user") // [K] 路由前缀
@CrossOrigin // [K] 允许跨域
public class UserController {

    @Autowired
    private UserService userService;

    // 注册
    @PostMapping("/register") // [K] POST 请求映射
    public Result register(@RequestBody User user) { // [K] 接收 JSON 请求体
        return Result.ok(userService.register(user));
    }

    // 登录
    @PostMapping("/login")
    public Result login(@RequestBody User user) {
        User u = userService.login(user.getUsername(), user.getPassword());
        if (u == null) return Result.fail("用户名或密码错误");
        return Result.ok(u);
    }

    // 查询全部
    @GetMapping("/list") // [K] GET 请求映射
    public Result list() {
        List<User> list = userService.list();
        return Result.ok(list);
    }

    // 新增
    @PostMapping("/add")
    public Result add(@RequestBody User user) {
        userService.add(user);
        return Result.ok();
    }

    // 修改
    @PutMapping("/update") // [K] PUT 请求映射
    public Result update(@RequestBody User user) {
        userService.update(user);
        return Result.ok();
    }

    // 删除
    @DeleteMapping("/delete/{id}") // [K] DELETE 请求映射 + 路径参数
    public Result delete(@PathVariable Integer id) { // [K] 取路径参数
        userService.delete(id);
        return Result.ok();
    }
}
